const inputItems = $input.all();

const allReturns = [];

for (const item of inputItems) {
  const returns = item.json?.returns;

  if (Array.isArray(returns)) {
    allReturns.push(...returns);
  }
}

// Удаляем дубли по ID возврата.
// Если один и тот же возврат встретился несколько раз,
// сохраняем последнюю полученную версию.
const uniqueReturns = new Map();

for (const ret of allReturns) {
  if (ret?.id != null) {
    uniqueReturns.set(String(ret.id), ret);
  }
}

const rows = [];

for (const ret of uniqueReturns.values()) {
  rows.push({
    json: {
      return_id: ret.id,

      company_id: ret.company_id,

      type: ret.type,
      schema: ret.schema,

      order_id: ret.order_id,
      order_number: ret.order_number,
      posting_number: ret.posting_number,

      sku: ret.product?.sku ?? null,
      offer_id: ret.product?.offer_id ?? null,
      product_name: ret.product?.name ?? null,
      price: ret.product?.price?.price ?? null,
      quantity: ret.product?.quantity ?? null,

      return_reason: ret.return_reason_name ?? null,

