const result = [];

for (const item of $input.all()) {
  const d = item.json;

  const avgProfit = Number(d.avg_profit || 0);
  const orders = Number(d.orders_count || 0);

  let priority = 'LOW';
  const reasons = [];
  let recommendedAction = 'Наблюдать';

  // Низкая прибыль
  if (d.profit_alert === 'HIGH') {
    priority = 'HIGH';
    reasons.push('Низкая средняя прибыль');

    recommendedAction =
      'Проверить причины низкой прибыльности. ' +
      'Цену автоматически не менять.';
  }

  // Высокая логистика
  if (d.logistics_alert === 'HIGH') {
    priority = 'HIGH';
    reasons.push('Высокая стоимость логистики');

    if (recommendedAction === 'Наблюдать') {
      recommendedAction =
        'Проверить стоимость логистики и влияние схемы доставки.';
    }
  } else if (d.logistics_alert === 'MEDIUM') {
    if (priority === 'LOW') {
      priority = 'MEDIUM';
    }

    reasons.push('Повышенная стоимость логистики');
  }

  // Высокая комиссия
  if (d.commission_alert === 'HIGH') {
    priority = 'HIGH';
    reasons.push('Высокая комиссия');

    if (recommendedAction === 'Наблюдать') {
      recommendedAction =
        'Проверить комиссию OZON и условия продажи товара.';
    }
  } else if (d.commission_alert === 'MEDIUM') {
    if (priority === 'LOW') {
      priority = 'MEDIUM';
    }

    reasons.push('Повышенная комиссия');
  }

  // Недостаточно данных
  if (orders < 10) {
    if (priority === 'LOW') {
      priority = 'MEDIUM';
    }

    reasons.push('Недостаточно продаж для уверенного решения');

    recommendedAction =
      'Наблюдать. Не принимать решение об изменении цены.';
  }

  result.push({
    json: {
      offer_id: d.offer_id,
      product_name: d.product_name,

      priority,

      orders_count: orders,
      avg_profit: avgProfit,
      avg_commission: Number(d.avg_commission || 0),
      avg_logistics: Number(d.avg_logistics || 0),
      avg_payout: Number(d.avg_payout || 0),

      current_price: Number(d.current_price || 0),
      cost_price: Number(d.cost_price || 0),

      profit_alert: d.profit_alert,
      logistics_alert: d.logistics_alert,
      commission_alert: d.commission_alert,

      reasons: reasons.join('; '),
      recommended_action: recommendedAction
    }
  });
}

return result;

