const rows = [];

const postings = $input.first().json.result?.postings ?? [];

for (const posting of postings) {

  const analytics = posting.analytics_data ?? {};
  const financial = posting.financial_data ?? {};

  rows.push({
    json: {
      posting_number: posting.posting_number ?? null,
      order_number: posting.order_number ?? null,

      city: analytics.city ?? null,
      region: analytics.region ?? null,
      district: analytics.district ?? null,

      delivery_type: analytics.delivery_type ?? null,

      warehouse: analytics.warehouse ?? null,
      warehouse_id: analytics.warehouse_id ?? null,

      tpl_provider: analytics.tpl_provider ?? null,
      tpl_provider_id: analytics.tpl_provider_id ?? null,

      cluster_from: financial.cluster_from ?? null,
      cluster_to: financial.cluster_to ?? null,

      updated_from_ozon: new Date().toISOString()
    }
  });
}

return rows;
